def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_min_args(args, 3, "apply FILE COLUMN TRANSFORM...")
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


SORT_MODIFIERS = ("num", "desc")


def parse_sort_key(key):
    """(column, numeric, descending) from `COLUMN[:num][:desc]` in either order."""
    column, *mods = key.split(":")
    if not column:
        raise UsageError("sort: empty column name in key %r" % key)
    for mod in mods:
        if mod not in SORT_MODIFIERS:
            raise UsageError("sort: unknown modifier %r in key %r (use num or desc)" % (mod, key))
    if len(set(mods)) != len(mods):
        raise UsageError("sort: modifier given twice in key %r" % key)
    return column, "num" in mods, "desc" in mods


def cmd_sort(args, opts):
    _need_min_args(args, 2, "sort FILE KEY...")
    keys = [parse_sort_key(k) for k in args[1:]]
    table = load(args[0])
    positions = [table.index(column) for column, _, _ in keys]
    numbers = {}
    for number, row in enumerate(table.rows, 1):
        for (column, numeric, _), at in zip(keys, positions):
            if numeric:
                numbers[number, at] = _need_cell_number(table, number, column, row[at])
    order = list(range(len(table.rows)))
    for (column, numeric, desc), at in reversed(list(zip(keys, positions))):
        if numeric:
            order.sort(key=lambda i: numbers[i + 1, at], reverse=desc)
        else:
            order.sort(key=lambda i: table.rows[i][at], reverse=desc)
    return table.with_rows([table.rows[i] for i in order])


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def parse_condition(arg):
    """(column, operator, value) from `COLUMN OP VALUE`: the first operator in the argument, the longer one on a tie."""
    for at in range(len(arg)):
        for op in FILTER_OPERATORS:
            if arg.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column name before the operator in %r" % arg)
                return arg[:at], op, arg[at + len(op):]
    raise UsageError("filter: no operator in condition %r (use ==, !=, >=, <=, >, < or ~)" % arg)


def _condition_holds(cell, op, value, number):
    if op == "~":
        return value.lower() in cell.lower()
    left = to_decimal(cell) if number is not None else None
    a, b = (left, number) if left is not None else (cell, value)
    return {"==": a == b, "!=": a != b, ">=": a >= b, "<=": a <= b, ">": a > b, "<": a < b}[op]


def cmd_filter(args, opts):
    _need_min_args(args, 2, "filter FILE CONDITION...")
    conditions = [parse_condition(c) for c in args[1:]]
    table = load(args[0])
    tests = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_condition_holds(row[at], op, value, number) for at, op, value, number in tests)])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by KEY (COLUMN[:num][:desc])"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every CONDITION (COLUMN OP VALUE) holds"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    options = " ".join("[--%s %s]" % (name, "|".join(allowed)) for name, (allowed, _) in VALUE_OPTIONS.items())
    lines = ["usage: %s %s COMMAND ARGS..." % (PROG, options), "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts = {name: default for name, (_, default) in VALUE_OPTIONS.items()}
    rest, i = [], 0
    while i < len(argv):
        arg = argv[i]
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in VALUE_OPTIONS:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            allowed = VALUE_OPTIONS[name][0]
            if value not in allowed:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(allowed), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:
        # stdout cannot be written (a full disk, say): say so, and keep the exit-time flush from failing again.
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
# Commands

`tabula [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS...` reads CSV files (UTF-8, an optional byte order mark, LF or CRLF) and prints
a table. Every command returns a `Table`; `--format` says how it is printed (text by default). A mistake in a file or in a
request exits 1 with `tabula: <message>` on standard error; a command line that is not shaped right exits 2.
`--kind` and `--keep` are read by one command each (`join` and `dedupe`) but are accepted on any command line, before or after the
command, as `--opt value` or `--opt=value`; any other value is a usage error.

## show

`tabula show FILE` prints the whole table. Blank lines in the file are ignored. A row with more or fewer fields than the
header is a mistake that names the file and the line (`t.csv: line 3: expected 2 fields, found 1`).

## head

`tabula head FILE N` prints the header and the first N rows. N is a whole number (zero is fine); anything else is a usage
error.

## cols

`tabula cols FILE` prints one row per column with two columns, `position` (from 1) and `column`.

## apply

`tabula apply FILE COLUMN TRANSFORM...` runs each TRANSFORM, left to right, over every value of one column and prints the
whole table. A transform is `name` or `name:ARG`; the list is in `docs/transforms.md`. A value a transform cannot take is
a mistake that names the file and the row (`t.csv: row 2: 'abc' is not a number`). Rows count from 1, the header not
counted.

## sort

`tabula sort FILE KEY...` prints the rows sorted by the first KEY, ties by the second, and so on. A KEY is a column name,
optionally followed by the modifiers `:num` (compare as numbers, not as text) and `:desc` (largest first), in either order
(`price:num:desc`, `price:desc:num`). Text compares by code point, so `B` sorts before `a`. The sort is stable: rows that tie
on every key keep the order of the file, also with `:desc`. With `:num`, a cell that is not a number (an empty cell is not
one) is a mistake that names the file, the row in file order and the column (`t.csv: row 2: column 'price': 'abc' is not a
number`). An unknown modifier, a modifier given twice in one KEY, an empty column name or no KEY at all is a usage error.

## filter

`tabula filter FILE CONDITION...` prints the rows where every CONDITION holds, in the order of the file. A CONDITION is one
argument shaped `COLUMN OP VALUE` with no spaces added: `price>=10`, `city==Leeds`, `name~gnome`. The operators are `==`,
`!=`, `>=`, `<=`, `>`, `<` and `~` (the cell contains VALUE, ignoring upper and lower case; an empty VALUE matches every
row). The operator is the first one that appears in the argument, so a column name cannot contain one of them; where two
start at the same place the longer one wins (`>=` and not `>`). For every operator but `~`, when both the cell and VALUE are
numbers they are compared as numbers (`10` is greater than `9`, `1.0` equals `1`); otherwise as text, by code point. VALUE
may be empty (`city==` matches the rows whose city is empty). A table with no row left still prints its header. An argument
with no operator, nothing before the operator, or no CONDITION at all is a usage error; a column the file does not have is a
mistake (`t.csv: no column 'zip' (columns: name, price)`).
# tabula

Small tools for CSV tables, standard library only (Python 3.9 or newer).

    tabula [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS...

Commands (`docs/commands.md` describes them, `docs/transforms.md` the transforms):

- `show FILE`: print a table
- `head FILE N`: the first N rows
- `cols FILE`: the column names, numbered
- `apply FILE COLUMN TRANSFORM...`: run transforms over one column
- `sort FILE KEY...`: rows sorted by one or more keys (`COLUMN[:num][:desc]`)
- `filter FILE CONDITION...`: rows where every condition (`COLUMN OP VALUE`, e.g. `price>=10`) holds

Everything lives in `tabula/engine.py`: the table model, the transforms, the output formats and the commands.
A command is a function `cmd_NAME(args, opts)` returning a `Table`, registered in `COMMANDS`.
Mistakes in a file or a request exit 1 with `tabula: <message>` on stderr; a badly shaped command line exits 2.
Run the tests with `python -m unittest discover tests`.
